def group_updates(updates):
    updates = sorted(updates, key=lambda x: x[0])
    result = []
    current_key = None
    current_values = []

    for key, value in updates:
        if key != current_key:
            if current_key is not None:
                result.append((current_key, current_values))
            current_key = key
            current_values = [value]
        else:
            current_values.append(value)

    if current_key is not None:
        result.append((current_key, current_values))

    return result

def merge_config(base, patch):
    if not isinstance(base, dict) or not isinstance(patch, dict):
        return patch if patch is not None else base
    result = base.copy()
    for key, value in patch.items():
        if key not in result:
            result[key] = value
        elif isinstance(value, dict) and isinstance(result[key], dict):
            result[key] = merge_config(result[key], value)
        else:
            result[key] = value
    return result

from pathlib import Path
from datetime import datetime

def report_paths(root):
    return sorted((datetime.strptime(path.name.split('-')[1], '%Y-%m-%d'), path) for path in Path(root).glob('report-*.csv'))

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("page, size, and total must be nonnegative")
    start = page * size
    stop = min(start + size, total)
    return start, stop

def summarize_jobs(jobs):
    summary = {}
    for job in jobs:
        status = job.status
        size = job.size
        if status not in summary:
            summary[status] = (0, 0)
        summary[status] = (summary[status][0] + 1, summary[status][1] + size)
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}

def retry_read(read, attempts):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    for attempt in range(attempts):
        try:
            return read()
        except TimeoutError:
            pass
    raise ValueError("all attempts failed")

def iter_unique_events(events):
    seen_ids = set()
    for event in events:
        if event.get('id') is not None:
            seen_ids.add(event['id'])
        yield event

def render_row(fields, record, missing="-"):
    def escape(value):
        return value.replace("\\", "\\\\").replace("\n", "\\n").replace("\t", "\\t")

    def render_field(field):
        if field not in record:
            return missing
        value = record[field]
        if value is None:
            return missing
        if value is False:
            return "false"
        if value is True:
            return "true"
        return escape(str(value))

    return "\t".join(render_field(field) for field in fields)

def write_all(write, data):
    if not data:
        return 0

    total_written = 0
    while data:
        bytes_written = write(data)
        if bytes_written == 0:
            raise OSError("write returned zero")
        if bytes_written < 0:
            raise OSError("write returned a negative number")
        if bytes_written > len(data):
            raise OSError("write returned a count larger than the offered slice")
        total_written += bytes_written
        data = data[bytes_written:]

    return total_written

def attach_readings(sensors, latest):
    readings = []
    for sensor in sensors:
        reading = latest.get(sensor['sensor_id'], None)
        readings.append({**sensor, 'reading': reading})
    return readings

def coerce_field(value):
    if value is None:
        return None
    elif isinstance(value, bool):
        return 'true' if value else 'false'
    elif isinstance(value, str):
        return value.strip()
    elif isinstance(value, (int, float)):
        return str(value)
    else:
        raise TypeError("Unsupported type for coercion")

def total_coverage(spans):
    if not spans:
        return 0

    spans.sort(key=lambda x: x[0])
    total = 0
    current_end = -float('inf')

    for start, end in spans:
        if end < start:
            raise ValueError("End must be greater than start")
        if current_end < start:
            total += end - start
        current_end = max(current_end, end)

    return total

def ttl_lookup(cache, key, now, fetch, ttl):
    if key not in cache:
        return None
    entry = cache[key]
    if entry[0] > now:
        return entry[1]
    try:
        result = fetch(key)
        cache[key] = (now + ttl, result)
        return result
    except Exception as e:
        cache[key] = entry  # Preserve the original entry
        raise e

def select_manifest(root):
    import os
    import fnmatch

    def is_manifest(path):
        return fnmatch.fnmatch(path, '*.manifest')

    def is_skip(path):
        return path.startswith('.') or path.endswith('.manifest')

    def get_relative_path(path):
        return os.path.relpath(path, root)

    def get_sorted_paths(root):
        return sorted([get_relative_path(path) for path in os.listdir(root) if is_manifest(path) and not is_skip(path)])

    return get_sorted_paths(root)

def first_unique(values, count):
    if count <= 0:
        return []
    seen = set()
    result = []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
            if len(result) == count:
                break
    return result

def encode_frame(payload):
    if len(payload) > 65535:
        raise ValueError("Payload length exceeds 65535 bytes")
    return payload[:2].to_bytes(2, byteorder='big') + payload[2:]

def wait_microseconds(start, end):
    if not (isinstance(start, datetime.datetime) and isinstance(end, datetime.datetime)):
        raise ValueError("Both arguments must be datetime.datetime objects")
    if start > end:
        raise ValueError("start datetime must be less than end datetime")
    delta = end - start
    return delta.total_seconds() * 1000000

def capture_append(target):
    def wrapper(*args, **kwargs):
        if not hasattr(wrapper, 'items'):
            wrapper.items = []
        wrapper.items.append((args, kwargs))
        return target(*args, **kwargs)
    return wrapper

def find_matches(records, columns, needle):
    needle = needle.lower()
    for record in records:
        for column in columns:
            if column in record and isinstance(record[column], str):
                if needle in record[column].lower():
                    yield record

def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("width must be non-negative")
    for row in rows:
        if not isinstance(row, list):
            raise ValueError("row must be a list")
        if len(row) > width:
            row = row[:width]
        elif len(row) < width:
            row.extend([fill] * (width - len(row)))
        yield row
